/bin/zsh -lc "python3 -B - <<'PY'
from backend import Backend, Duplicate
from service import save
backend = Backend()
result = save(backend, 'key', 'original')
assert result == {'created': None}
print('Direct backend creation:', result)
try:
    save(backend, 'key', 'replacement')
except Duplicate:
    print('Direct backend duplicate: Duplicate propagated')
else:
    raise AssertionError('Expected Duplicate')
assert backend.rows['key'] == 'original'
print('Original value preserved:', backend.rows['key'])
class Offline:
    def put(self, key, value):
        raise OSError('offline')
try:
    save(Offline(), 'key', 'value')
except OSError:
    print('Direct backend operational failure: OSError propagated')
else:
    raise AssertionError('Expected OSError')
PY"

